RBOOT = [
    ("Project-specific support", "RBoot has its own board configurations, release policy and region-preservation requirements. Historical Canoeboot support does not establish RBoot support. Confirm the exact target in rbmk and the selected RBoot release.", "https://rboot.org/docs/install/"),
    ("Preserve regions where required", "For supported Sandy/Ivy Bridge and Haswell boards, RBoot's procedure preserves existing vendor regions, including ME. Do not run Libreboot's vendor injection workflow on these images or write a whole image over regions RBoot omits. Review the exact region map and the project's Dell GbE migration guidance when applicable.", "https://rboot.org/docs/install/ivy_has_common.html"),
    ("Stage an authenticated inspection copy", "Download the exact RBoot target in the guided workflow, then choose Select and stage an actual ROM variant for inspection. LibreFren rechecks the archive hash and publisher signature before extraction. This creates an inspection copy, not a prepared whole-chip replacement. No Libreboot vendor-file injection is run. Keep the authenticated original and the extraction receipt.", "https://rboot.org/docs/install/ivy_has_common.html"),
    ("Compare the actual region boundaries", "Choose Compare backup and candidate image layouts, then RBoot vendor-region preservation. Supply a complete current backup from the target and the staged candidate. Review descriptor, BIOS, ME, GbE and platform-data offsets and lengths. The app does not inspect every chipset-specific region or protection register; it cannot establish the current firmware state from these files alone. A layout difference requires a reviewed migration plan, even if both images have the same total size.", "https://rboot.org/docs/install/ivy_has_common.html"),
    ("Resolve the GbE migration hazard", "RBoot documents cases where a 16 KiB GbE region replaces an 8 KiB region used by another distribution. Writing that larger range can overwrite the beginning of the existing ME region. If the comparison reports an overlap, stop. Do not change MAC addresses using a generic injection command, resize a region, or replace the descriptor to hide the mismatch. Follow the exact board's migration guidance and preserve the original region layout and recovery backup.", "https://rboot.org/docs/install/dell_gbe.html"),
    ("Resolve multi-chip and conflicting instructions", "An image covering several chips is not a per-chip image. Confirm the physical chip order, capacities and address mapping from the exact board guide before splitting anything. RBoot's common preservation requirements still apply when another page shows a broad external-write example. If those instructions do not explain how the existing vendor regions remain intact for your current layout, stop; this companion does not generate a replacement write command from that example.", "https://rboot.org/docs/install/ivy_has_common.html"),
]


def guide_for(board):
    result = list(GENERAL)
    documents = board.get('documentation', [])
    result.insert(0, ('Board-specific source review',
                     'Exact target: ' + board['id'] + '. These references mention this identifier; they are not automatically approved procedures. Read their prerequisites, compare the physical target and current firmware, and resolve the full flash layout. ' + ('\n\n' + '\n'.join(documents) if documents else 'No exact guide mapping has been reviewed. Follow the source link and find the matching board documentation before progressing.'),
                     board['source']))
    if board['project'] == 'rboot':
        result = RBOOT + result
    identifiers = ' '.join([board['id'], board.get('directory', ''), *board.get('selectors', [])]).lower()
    if any(x in identifiers for x in ('cros_', 'google', 'chromebook')):
        result = CHROMEBOOK + result
    return result
